insert into public.hwarang_learning_content(id,data) values('fp-foundation-v2',$course${"id": "fp-foundation-v2", "kind": "course", "category": "new_hire", "permission": "academy.new_hire", "title": "FP 기초 과정 · 고객 미션", "summary": "5개 챕터 · 핵심 수업 15개와 종합 실습 3개", "learning_mode": "practice", "interactive": true, "published": true, "revision": 1, "pass_percent": 100, "updated_on": "2026-11-14", "lessons": [{"id": "l01", "day": 1, "title": "보험이 해결하는 문제와 상담의 흐름", "chapter": 0, "mentor_required": false, "quiz": [{"id": "pick", "question": "상담을 이어갈 첫 행동은 무엇일까요?", "options": ["가장 큰 보장부터 바로 추천한다", "걱정하는 기간과 생활비, 준비된 자금을 질문한다", "보험이면 생활비 문제가 모두 해결된다고 말한다"], "answer": 1}, {"id": "transfer", "question": "먼저 할 일은?", "options": ["기존 계약을 모두 정리한다", "보험료가 낮은 상품만 보여준다", "부담 수준과 기존 계약을 확인한다"], "answer": 2}]}, {"id": "l02", "day": 2, "title": "보험계약 한 장 읽기", "chapter": 0, "mentor_required": false, "quiz": [{"id": "roles", "question": "가상 증권 A 역할", "options": ["다른 배치", "서연 / 하준 / 하준"], "answer": 1}, {"id": "amounts", "question": "보험료 / 가입금액 / 지급액", "options": ["다른 배치", "5만 / 1000만 / 500만"], "answer": 1}, {"id": "period", "question": "25년 시점", "options": ["납입 중", "납입 종료 · 보장 유지"], "answer": 1}, {"id": "final", "question": "새 증권 B", "options": ["다른 배치", "도윤 / 도윤 / 지우 · 월 8만원 · 납입 종료·보장 유지 · 지정 근거"], "answer": 1}]}, {"id": "l03", "day": 3, "title": "계약 조건의 근거 찾기", "chapter": 0, "mentor_required": false, "quiz": [{"id": "pick", "question": "이 계약을 설명할 때 우선 대조할 자료는?", "options": ["지금 배포하는 홍보물만 본다", "고객 계약에 적용되는 약관·특약과 가입 자료를 대조한다", "상품 이름이 같으니 조건도 같다고 본다"], "answer": 1}, {"id": "transfer", "question": "설명에는 어떻게 표시할까요?", "options": ["유리한 조건을 확정해 안내한다", "적용 문서 확인이 필요하다고 구분한다", "두 조건의 중간값으로 안내한다"], "answer": 1}]}, {"id": "l04", "day": 4, "title": "첫 연락과 상담 약속", "chapter": 1, "mentor_required": false, "quiz": [{"id": "pick", "question": "어떤 답변으로 이어갈까요?", "options": ["담당자니까 주민번호부터 알려 달라고 한다", "상품이 좋다는 이야기부터 시작한다", "소속·이름·연락 목적과 확인 가능한 공식 경로를 안내한다"], "answer": 2}, {"id": "transfer", "question": "다음 응