 상담 동행", "optional": true, "mentor_required": false, "quiz": []}, {"id": "f3", "day": 0, "title": "동료와 말로 연습", "optional": true, "mentor_required": false, "quiz": []}, {"id": "f4", "day": 0, "title": "피드백 반영 확인", "optional": true, "mentor_required": false, "quiz": []}]}$course$::jsonb) on conflict(id) do nothing;

create table public.hwarang_learning_work_events (
 id bigint generated always as identity primary key,
 user_id uuid not null references public.profiles(id), content_id text not null,
 revision integer not null, lesson_id text not null, version integer not null,
 snapshot jsonb not null, recorded_at timestamptz not null default now(),
 unique(user_id,content_id,revision,lesson_id,version)
);
alter table public.hwarang_learning_work_events enable row level security;
revoke all on public.hwarang_learning_work_events from public,anon,authenticated;
grant select,insert on public.hwarang_learning_work_events to service_role;
grant usage on sequence public.hwarang_learning_work_events_id_seq to service_role;

create function private.fp_learning_audit() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
 if new.content_id='fp-foundation-v2' then
  -- Inspection release: only super-admin learners can create or change work.
  if not exists(select 1 from public.profiles where id=new.user_id and role='super_admin' and is_active) then
   raise exception 'COURSE_UNDER_REVIEW';
  end if;
  insert into public.hwarang_learning_work_events(user_id,content_id,revision,lesson_id,version,snapshot)
  values(new.user_id,new.content_id,new.revision,new.lesson_id,new.version,to_jsonb(new));
 end if;
 return new;
end $$;
revoke all on function private.fp_learning_audit() from public,anon,authenticated;
grant execute on function private.fp_learning_audit() to service_role;
create trigger fp_learning_audit after insert or update on public.hwarang_learning_work
for each row execute function private.fp_learning_audit();

create function public.hwarang_learning_interactive_save(p_actor uuid,p_id text,p_revision integer,p_lesson text,p_version integer,p_answers jsonb,p_submit boolean)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare d jsonb; l jsonb; q jsonb; note text; chosen text;
begin
 perform private.learning_check(p_actor);
 if p_id is distinct from 'fp-foundation-v2' or not exists(select 1 from public.profiles where id=p_actor and role='super_admin' and is_active) then raise exception 'COURSE_UNDER_REVIEW';end if;
 select data into d from public.hwarang_learning_content where id=p_id for share;
 select x into l from jsonb_array_elements(d->'lessons') x where x->>'id'=p_lesson;
 if l is null then raise exception 'INVALID_LESSON';end if;
 if coalesce((l->>'optional')::boolean,false) and p_submit then raise exception 'OPTIONAL_DRAFT_ONLY';end if;
 note:='학습자가 화면에서 선택한 행동을 자동으로 정리한 실습 기록입니다.'||chr(10)||(l->>'title');
 for q in select * from jsonb_array_elements(l->'quiz') loop
  chosen:=p_answers->>(q->>'id');
  if chosen is not null and chosen !~ '^[0-9]{1,2}$' then raise exception 'INVALID_CHOICE';end if;
  if chosen is not null and chosen::integer>=jsonb_array_length(q->'options') then raise exception 'INVALID_CHOICE';end if;
  note:=note||chr(10)||(q->>'question')||': '||coalesce(q->'options'->>(chosen::integer),'미선택');
 end loop;
 return public.hwarang_learning_work_save(p_actor,p_id,p_revision,p_lesson,p_version,p_answers,note,p_submit);
end $$;
revoke all on function public.hwarang_learning_interactive_save(uuid,text,integer,text,integer,jsonb,boolean) from public,anon,authenticated;
grant execute on function public.hwarang_learning_interactive_save(uuid,text,integer,text,integer,jsonb,boolean) to service_role;
commit;
